    contentHtml: `<!-- target keyword: 십천간 | secondary: 천간 해석, 일간 특성, 갑목 을목 차이 -->
<p>십천간(十天干)은 갑(甲)·을(乙)·병(丙)·정(丁)·무(戊)·기(己)·경(庚)·신(辛)·임(壬)·계(癸) 열 개의 부호로, 오행(목화토금수)을 음양으로 나눈 사주의 기본 언어입니다. 특히 태어난 날의 천간인 일간(日干)은 사주 해석의 중심축으로, 내 기질과 에너지 사용 방식을 읽는 첫 번째 열쇠가 됩니다.</p>
<h2>십천간이란: 오행 다섯을 음양으로 나눈 열 개의 기운</h2>
<p>천간은 하늘의 기운, 즉 겉으로 드러나는 성향과 지향을 나타냅니다. 목(木)은 갑·을, 화(火)는 병·정, 토(土)는 무·기, 금(金)은 경·신, 수(水)는 임·계로 나뉘며, 앞 글자가 양(陽), 뒤 글자가 음(陰)입니다. 같은 오행이라도 양간은 크고 직진하는 에너지, 음간은 섬세하고 스며드는 에너지로 작동합니다.</p>
<p>주의할 점은 천간 한 글자로 사람 전체를 단정하지 않는 것입니다. 같은 경금(庚金)이라도 어느 기둥에 있는지, 월령의 계절 기운을 받는지, 지지에 통근(通根)했는지, 합·충 관계가 작동하는지에 따라 전혀 다르게 움직입니다. 팔자 전체 구조가 궁금하다면 <a href="/insights/saju-four-pillars-basics/">사주팔자 기초 가이드</a>에서 여덟 글자의 뼈대를 먼저 잡아 두세요.</p>
<h2>갑목·을목: 성장과 조율의 목(木) 기운</h2>
<p>갑목(甲木)은 곧게 솟는 큰 나무의 양목입니다. 방향 제시, 추진력, 자기 원칙이 강해 기획·창업·교육처럼 판을 이끄는 역할에서 강점이 살아납니다. 다만 고집이 세어 꺾이는 것보다 부러지는 쪽을 택하기 쉬우니 유연성이 과제입니다.</p>
<p>을목(乙木)은 덩굴과 화초의 음목으로, 환경에 맞춰 휘어지며 자라는 생존력이 특기입니다. 관계 조율, 협상, 섬세한 기획에 강하고 적응이 빠릅니다. 두 일간 모두 수(水)의 생조를 받아 화(火)로 발산하는 구조라, 수가 마르면 성장이 멎고 화가 과하면 소모가 커집니다.</p>
<h2>병화·정화: 표현과 정밀의 화(火) 기운</h2>
<p>병화(丙火)는 태양의 양화로 존재감과 확산력이 큽니다. 발표, 홍보, 무대처럼 드러나는 자리에서 빛나지만 감정 과열과 번아웃이 약점이라 냉각 루틴이 필요합니다. 정화(丁火)는 촛불과 등불의 음화로, 한 점을 오래 밝히는 집중력과 정밀함이 강점입니다. 병화가 오픈 무대형이라면 정화는 전문 지식 기반의 장인형으로, 같은 화라도 쓰임이 다릅니다.</p>
<h2>무토·기토: 안정과 관리의 토(土) 기운</h2>
<p>무토(戊土)는 큰 산의 양토로 묵직한 신뢰감과 책임감이 특징입니다. 조직의 버팀목 역할을 자연스럽게 맡지만 혼자 짊어지다 지치기 쉬워 위임이 과제입니다. 기토(己土)는 논밭의 음토로 현실 감각, 세밀한 관리, 정보 정리에 강합니다. 두 일간 모두 화의 생조를 받고 목의 극을 받는 구조이므로, 인성과 비겁의 조화가 실전 해석의 핵심입니다.</p>
<h2>경금·신금: 결단과 정제의 금(金) 기운</h2>
<p>경금(庚金)은 원석과 도끼의 양금으로 결단력과 직설적 추진이 강점입니다. 다만 말의 날이 서서 관계에 상처를 주고받기 쉬우니 표현의 완충이 필요합니다. 신금(辛金)은 세공된 보석의 음금으로 품질 기준, 심미안, 전문성이 뛰어나지만 완벽주의와 비판 민감성이 약점입니다. 금 일간은 화(火)로 제련될 때 그릇이 커지는 구조임을 기억하면 대운 해석이 선명해집니다.</p>
<h2>임수·계수: 지혜와 통찰의 수(水) 기운</h2>
<p>임수(壬水)는 바다와 강의 양수로 정보 수집, 전략적 사고, 네트워크 확장에 강하지만 선택지가 많아 결정이 늦어지는 편입니다. 계수(癸水)는 이슬과 빗물의 음수로 직관, 감수성, 깊은 통찰이 강점이며 감정 소모 관리가 과제입니다. 수 일간은 목(木)으로 에너지를 출력하고 토(土)의 제방으로 방향을 잡는 구조입니다.</p>
<h2>십천간을 실전에 쓰는 순서</h2>
<ul>
  <li>1단계: 만세력에서 내 일간을 확인하고 위 열 가지 중 기본 기질을 파악한다.</li>
  <li>2단계: 월지의 계절이 내 일간을 돕는지 확인한다 — 지지의 계절성은 <a href="/insights/twelve-earthly-branches-and-seasons/">십이지지 가이드</a> 참고.</li>
  <li>3단계: 일간의 강약에 따라 필요한 오행을 가늠한다 — 판단법은 <a href="/insights/yongshin-how-to-think/">용신 찾는 법</a>에서 다룬다.</li>
  <li>4단계: 키워드 단정 대신 "이 기운이 어떤 환경에서 이점이 되는가"로 번역한다.</li>
</ul>
<p><strong>내 일간이 열 가지 중 무엇인지 궁금하다면</strong> 연이가 일간 확인부터 기질 해석까지 바로 풀어 드립니다. <a href="/saju/">무료 사주 분석 바로가기</a></p>`,
