    contentHtml: `<!-- target keyword: 용신 찾는 법 | secondary: 용신, 신강신약, 억부용신 -->
<p>용신(用神) 찾는 법의 핵심은 일간의 강약, 즉 신강신약을 먼저 판단하고 사주의 균형을 잡아 주는 오행을 고르는 것입니다. 신강하면 기운을 덜어 내는 오행이, 신약하면 나를 돕는 오행이 용신 후보가 됩니다. 이 글은 신강신약 판단부터 억부·조후·통관 용신의 구분, 생활 적용까지 순서대로 안내합니다.</p>
<h2>용신이란 무엇인가: 사주의 균형을 잡는 핵심 오행</h2>
<p>용신은 사주 원국에서 그 사람에게 가장 필요한 기운, 즉 치우친 팔자를 안정시키는 오행을 말합니다. 사주가 신강(身强)하면 넘치는 힘을 설기(泄氣)하거나 제어하는 오행이, 신약(身弱)하면 일간을 생(生)하거나 도와주는 오행이 용신이 됩니다.</p>
<p>흔한 오해는 "평생 용신은 단 하나"라는 생각입니다. 원국의 용신이라는 중심축은 있지만, 대운과 세운의 흐름에 따라 실제로 요긴하게 쓰이는 기운은 달라집니다. 용신은 정답 맞히기 퀴즈가 아니라 내 사주의 균형 상태를 진단하는 사고법으로 접근해야 합니다.</p>
<h2>신강신약 판단: 용신 찾기의 첫 단계</h2>
<p>용신을 잘못 잡는 가장 흔한 원인이 신강신약 판단 오류입니다. 신강신약은 한 가지 지표가 아니라 여러 조건을 종합해 판단합니다. <a href="/insights/saju-four-pillars-basics/">사주팔자 기초</a>가 흔들리면 이 단계부터 어긋나므로 천간지지 구조를 먼저 익혀 두세요.</p>
<ul>
  <li>득령(得令): 월지(月支)가 일간을 돕는 계절인가 — 가장 큰 비중</li>
  <li>득지(得地): 일간이 지지에 통근(通根)해 뿌리를 내렸는가</li>
  <li>득세(得勢): 비겁과 인성이 천간·지지에서 세력을 이루는가</li>
  <li>합충 변수: 형(刑)·충(沖)·합(合)으로 힘의 구조가 변하지 않는가</li>
</ul>
<p>예를 들어 일간이 계절을 얻지 못했더라도 지지에 뿌리가 깊고 인성의 생조가 든든하면 실제로는 약하지 않은 경우가 많습니다. 반대로 월지를 얻었어도 충으로 뿌리가 흔들리면 겉보기보다 약할 수 있습니다.</p>
<h2>용신의 종류: 억부·조후·통관·병약·전왕</h2>
<p>전통적으로 용신을 정하는 관점은 크게 다섯 가지로 정리됩니다. 서로 배타적인 것이 아니라 사주의 상태에 따라 우선순위가 달라지는 진단 도구입니다.</p>
<ul>
  <li><strong>억부용신(抑扶用神)</strong>: 강하면 눌러 주고(抑) 약하면 도와주는(扶) 가장 기본적인 방식</li>
  <li><strong>조후용신(調候用神)</strong>: 한난조습(寒暖燥濕)을 조절 — 겨울 사주에 화(火), 여름 사주에 수(水)처럼 기후 균형을 먼저 봄</li>
  <li><strong>통관용신(通關用神)</strong>: 두 세력이 팽팽히 싸울 때 사이를 이어 흐름을 트는 중간 오행</li>
  <li><strong>병약용신(病藥用神)</strong>: 사주의 병(病)이 되는 글자를 제거하거나 다스리는 약(藥) 역할의 오행</li>
  <li><strong>전왕용신(專旺用神)</strong>: 한 기운이 압도적일 때 거스르지 않고 그 흐름을 따르는 특수 격국의 방식</li>
</ul>
<h2>용신으로 세우는 실생활 전략 맵</h2>
<p>용신을 파악했다면 생활 배치로 번역할 차례입니다. 화(火)가 용신이면 표현하고 드러내는 활동과 활력 루틴을 늘리고, 수(水)가 용신이면 학습·휴식·유연한 사고의 비중을 키우는 식입니다. 직업 환경, 인간관계의 밀도, 하루 리듬까지 용신의 방향에 맞춰 조정할 수 있습니다.</p>
<p>더 중요한 것은 타이밍입니다. 대운·세운에서 용신 오행이 힘을 받는 시기에는 확장과 도전을, 기신(忌神)이 강해지는 시기에는 정비와 리스크 관리를 배치하면 같은 노력으로 더 큰 효율을 냅니다. 흐름 읽기는 <a href="/insights/ziwei-decade-and-annual-flow-reading-guide/">대운·유년 해석 가이드</a>의 프레임을 참고하세요.</p>
<h2>용신 해석에서 피해야 할 함정</h2>
<p>"당신의 용신은 X이니 Y가 일어난다"는 단정은 가장 위험한 사용법입니다. 용신은 사건 예언 장치가 아니라 균형 진단 도구이므로, "이 조건에서 A를 보완하면 B가 안정된다"는 조건부 문장으로 쓰는 것이 정확하고 안전합니다.</p>
<p>또 하나의 함정은 신강신약 판단 없이 부족한 오행을 무조건 용신으로 삼는 것입니다. 부족한 오행이 곧 용신은 아니며, 사주 전체의 힘의 구조를 본 뒤에야 용신이 정해집니다. 십성 구조와 함께 보면 판단이 더 정교해지니 <a href="/insights/ten-gods-beginner-map/">십성 입문 가이드</a>를 곁들여 읽어 보세요.</p>
<p><strong>내 사주의 용신이 궁금하다면</strong> 연이가 신강신약 판단부터 균형 전략까지 짚어 드립니다. <a href="/saju/">무료 사주 분석 바로가기</a></p>`,
