    title: "2026 병오년(丙午年) 종합 운세 — 재물·연애 포함 완전 가이드",
    description: "2026년 병오년은 병화·오화이 만나 화(火) 기운이 강하게 드러나는 해입니다. 재물운·직업운·연애운·건강운과 화가 많거나 부족한 사람의 대응법까지 정리했습니다.",
