        body:
          "베다점성술(Jyotish, 조티시)은 5,000년 이상의 역사를 가진 인도 전통 점성술 체계입니다. '조티시'는 산스크리트어로 '빛의 학문'을 의미하며, 인도의 전통 의학 아유르베다와 함께 베다 시대부터 전해 내려온 지식 체계입니다. 베다점성술과 서양 점성술은 모두 행성과 별자리를 활용하지만, 계산 방식과 해석 체계에서 큰 차이를 보입니다. 가장 큰 차이는 황도 기준입니다. 서양 점성술은 봄분점을 양자리 0도로 고정하는 열대 황도(Tropical Zodiac)를 사용하는 반면, 베다점성술은 실제 별들의 위치를 기반으로 한 항성 황도(Sidereal Zodiac)를 사용합니다. 이 때문에 같은 사람이라도 두 체계에서 별자리가 약 23도 차이가 날 수 있습니다.",
