    contentHtml: `<!-- target keyword: 자미두수 입문 | secondary: 자미두수 보는 법, 자미두수 12궁, 자미두수 명반 -->
<p>자미두수(紫微斗數)는 출생 연월일시로 12궁(宮)의 명반을 세우고 그 위에 배치된 별들의 조합을 읽는 중국 명학 체계입니다. 자미두수 입문의 핵심은 별 하나의 길흉이 아니라 궁위 문맥과 별들의 조합 관계를 읽는 것 — 이 글에서 명반 구조부터 주성·사화까지 순서대로 안내합니다.</p>
<h2>자미두수란 무엇인가: 구조 읽기의 철학</h2>
<p>이름의 '자미(紫微)'는 북두칠성 근처의 제좌성(帝座星)인 자미성을, '두수(斗數)'는 북두칠성 체계를 활용한다는 뜻입니다. 사주명리학이 여덟 글자의 간지(干支) 생극 관계를 분석한다면, 자미두수는 같은 출생 데이터를 12개의 궁에 펼치고 수십 개의 별을 배치해 삶의 영역별 지도를 그립니다.</p>
<p>그래서 자미두수는 "재물은 어떤 구조인가", "일은 어떤 방식이 맞는가"처럼 영역별 질문에 답하기 좋은 도구입니다. 두 체계의 관점 차이가 궁금하다면 <a href="/insights/saju-four-pillars-basics/">사주팔자 기초 가이드</a>와 비교해 읽어 보세요.</p>
<h2>자미두수 12궁: 삶의 영역을 12개로 나누다</h2>
<p>명반의 12궁은 각각 삶의 특정 영역을 담당합니다. 어떤 별이 어느 궁에 앉는지에 따라 같은 별도 전혀 다르게 작동합니다.</p>
<ul>
  <li>명궁(命宮): 기본 성향과 삶의 중심축</li>
  <li>재백궁(財帛宮): 재물 운용과 경제 감각</li>
  <li>관록궁(官祿宮): 직업과 사회적 성취</li>
  <li>부처궁(夫妻宮): 배우자와 깊은 관계</li>
  <li>자녀궁(子女宮): 자녀와 창의적 표현</li>
  <li>부모궁·복덕궁·전택궁·노복궁 등: 관계·내면 만족·자산 기반·협력자</li>
</ul>
<p>입문자는 명궁, 재백궁, 관록궁, 부처궁 네 궁부터 시작하면 실생활 질문의 대부분을 커버할 수 있습니다.</p>
<h2>주성(主星) 해석의 기본 태도: 단독 해석 금지</h2>
<p>자미, 천부, 무곡, 태양, 태음 같은 주성은 궁의 성향 축을 제공하지만 단독 해석은 오차가 큽니다. 반드시 삼방사정(三方四正) — 해당 궁을 비추는 세 궁과 마주 보는 궁 — 을 함께 보고, 보성(補星)의 보정까지 확인하는 습관이 필요합니다. 명궁에 좋은 별이 있어도 삼방에서 충격하는 조합이 들어오면 체감은 달라집니다.</p>
<h2>핵심 주성 5개 빠른 이해</h2>
<p>처음에는 대표 주성 5개부터 익히는 것이 좋습니다.</p>
<ul>
  <li><strong>자미성(紫微星)</strong>: 리더십과 권위, 책임감 — 인정받고자 하는 욕구가 동력</li>
  <li><strong>천부성(天府星)</strong>: 안정과 축적, 보수적 관리 — 기반을 지키는 힘</li>
  <li><strong>무곡성(武曲星)</strong>: 추진력과 결단, 실행 중심의 실용주의</li>
  <li><strong>태양성(太陽星)</strong>: 공개적 표현과 대외 활동, 베푸는 에너지</li>
  <li><strong>태음성(太陰星)</strong>: 내면의 풍요, 감수성, 조용한 축적</li>
</ul>
<p>같은 별이라도 명궁에 있을 때와 재백궁에 있을 때의 체감이 다르므로, 별 이름보다 "이 궁에서 이 별이 무엇을 하는가"를 묻는 것이 자미두수 보는 법의 정석입니다.</p>
<h2>사화(四化): 화록·화권·화과·화기의 변형 체계</h2>
<p>사화성(四化星)은 생년 천간에 따라 특정 별에 붙는 네 가지 변화 코드로, 명반 해석의 다이내믹을 만듭니다. 화록(化祿)은 풍요와 기회, 화권(化權)은 주도권과 통제력, 화과(化科)는 명예와 학문적 인정, 화기(化忌)는 지연과 과제를 뜻합니다.</p>
<p>재백궁 주성에 화록이 붙으면 재물 기회 확장의 신호로, 화기가 붙으면 재물 관리 점검의 신호로 읽습니다. 사화를 흐름 해석에 적용하는 방법은 <a href="/insights/ziwei-four-transformations-lu-quan-ke-ji-guide/">사화 실전 해석 가이드</a>와 <a href="/insights/ziwei-decade-and-annual-flow-reading-guide/">대운·유년 해석법</a>에서 이어집니다.</p>
<h2>자미두수 입문자를 위한 학습 순서</h2>
<ul>
  <li>1단계: 내 명반을 뽑아 명궁의 주성을 확인한다.</li>
  <li>2단계: 명궁·재백궁·관록궁·부처궁 네 궁의 주성 조합을 정리한다.</li>
  <li>3단계: 삼방사정으로 조합 관계를 확인하고 단독 해석을 교정한다.</li>
  <li>4단계: 사화의 위치로 올해의 기회와 과제를 구분한다.</li>
</ul>
<p>궁위별 핵심 질문 — 명궁은 "나는 어떤 에너지로 세상과 만나는가", 재백궁은 "나는 자원을 어떻게 운용하는가", 관록궁은 "어떤 일 방식이 맞는가" — 을 먼저 던지면 별 이름의 홍수 속에서도 길을 잃지 않습니다. 자미두수는 깊이 있는 도구이지만 항상 참고 정보로 활용하고, 중요한 결정은 본인의 판단을 중심에 두세요.</p>
<p><strong>내 명반이 궁금하다면</strong> 연이가 12궁과 주성 배치를 한눈에 정리해 드립니다. <a href="/ziwei/">무료 자미두수 명반 보기</a> · 대화형 해석은 <a href="/ziwei-ai/">자미두수 AI 상담</a>에서.</p>`,
