    title: "천동성(天同星) 완전 해설 — 자미두수의 복(福)과 행복, 온화함을 상징하는 별",
    description: "천동성은 자미두수에서 복덕·행복·온화함·공감을 대표하는 길성입니다. 기본 의미부터 성격·장단점·재물운·직업운·궁위별 해석·다른 주성과의 조합·개운법까지 정리했습니다.",
