<p>천동성은 자미두수에서 행복, 복덕, 배려, 공감, 평화를 상징하는 대표적인 길성입니다. 뛰어난 경쟁력으로 앞서 나가기보다 사람들과 조화를 이루며 안정적인 삶을 만들어 가는 데 강점을 가진 별입니다.</p>
