    contentHtml: `<!-- target keyword: 자미두수 12궁 | secondary: 명궁, 관록궁, 재백궁, 부처궁 -->
<p>자미두수 12궁은 명반을 12개의 삶의 영역으로 나눈 틀로, 같은 별도 어느 궁에 앉느냐에 따라 전혀 다르게 작동합니다. 12궁 전부를 외우기 전에 사람들이 가장 궁금해하는 네 자리 — 명궁(나), 관록궁(일), 재백궁(돈), 부처궁(관계) — 부터 잡으면 명반의 80%가 읽히기 시작합니다.</p>
<h2>12궁 전체 지도 한눈에 보기</h2>
<p>12궁은 명궁·형제궁·부처궁·자녀궁·재백궁·질액궁·천이궁·노복궁(교우궁)·관록궁·전택궁·복덕궁·부모궁으로 구성됩니다. 각 궁은 '삶의 질문' 하나씩을 담당한다고 보면 됩니다. 나는 어떤 사람인가(명궁), 어떻게 일하는가(관록궁), 돈을 어떻게 다루는가(재백궁), 관계를 어떻게 맺는가(부처궁), 밖에서는 어떤가(천이궁), 마음은 편안한가(복덕궁) — 이렇게 질문으로 기억하는 것이 가장 빠릅니다.</p>
<h2>명궁: 모든 해석의 출발점</h2>
<p>명궁은 타고난 기질, 기본 작동 방식, 인생의 큰 결을 보는 자리로 12궁의 중심입니다. 명궁의 주성이 무엇인지에 따라 나머지 궁을 읽는 톤이 정해지므로 반드시 먼저 확인해야 합니다. 명궁을 스스로 점검하는 방법은 <a href="/insights/ziwei-minggong-self-analysis-checklist/">명궁 자가분석 체크리스트</a>에 단계별로 정리되어 있습니다.</p>
<h2>관록궁: 일의 구조를 보는 자리</h2>
<p>관록궁(官祿宮)은 직무 성향, 성과를 내는 방식, 커리어의 흐름을 읽는 핵심 궁입니다. 여기서 중요한 건 '무슨 직업을 갖게 되는가'라는 예언이 아니라 '어떤 방식으로 일할 때 성과가 나는가'라는 작동 방식입니다. 예컨대 무곡이면 숫자와 구조 중심, 천동이면 조율과 지속 가능한 리듬 중심으로 읽습니다.</p>
<h2>재백궁: 돈의 습관을 보는 자리</h2>
<p>재백궁(財帛宮)은 수입의 크기보다 돈을 다루는 습관과 패턴을 보여줍니다. 충동형인지 계획형인지, 벌어서 쓰는 흐름인지 모아서 굴리는 흐름인지를 읽으면 현실적인 재무 전략이 나옵니다. 축적형 별들의 대표 사례는 <a href="/insights/ziwei-tianfu-star-wealth-and-stability/">천부성 해석</a>에서 확인할 수 있습니다.</p>
<h2>부처궁: 관계의 리듬을 보는 자리</h2>
<p>부처궁(夫妻宮)은 연애·결혼 상대의 유형보다 먼저, 내가 파트너십에서 기대하는 것과 소통 스타일을 보여주는 자리입니다. 갈등을 예언처럼 단정하기보다 '우리 조합에 필요한 대화 규칙'을 찾는 도구로 쓰는 것이 안전하고 실용적입니다.</p>
<h2>삼방사정: 궁을 혼자 읽지 않는 법</h2>
<p>자미두수의 실전 규칙 하나를 기억하세요. 궁은 홀로 읽지 않고 삼방사정(三方四正) — 그 궁과 마주 보는 대궁, 그리고 삼합을 이루는 두 궁 — 을 함께 봅니다. 명궁의 삼방은 관록궁·재백궁·천이궁이라, '나'를 읽을 때 일·돈·바깥 활동이 자동으로 엮입니다. 궁 하나의 별이 약해도 삼방에서 받쳐 주면 전혀 다른 해석이 됩니다.</p>
<ul>
  <li>1단계: 명궁 주성 확인 — 해석의 톤 결정</li>
  <li>2단계: 질문에 해당하는 궁(일=관록, 돈=재백, 관계=부처) 확인</li>
  <li>3단계: 그 궁의 삼방사정과 사화(록·권·과·기) 점검</li>
</ul>
<p>각 궁에 앉는 별들의 성격은 <a href="/insights/ziwei-14-main-stars-complete-guide/">14주성 완전정리</a>에서, 궁별 월간 점검 루틴은 <a href="/insights/ziwei-monthly-action-checklist-by-palace/">궁위별 월간 점검 템플릿</a>에서 이어집니다.</p>
<p><strong>내 12궁에 어떤 별이 앉아 있는지</strong> 지금 바로 <a href="/ziwei/">자미두수 무료 명반 보기</a>로 확인해 보세요. 일·돈·연애 종합 풀이는 <a href="/ziwei-ai/">자미두수 AI 상담</a>이 도와드립니다.</p>`,
