    description: "자미두수의 핵심은 별 하나가 아니라 별의 조합입니다. 조합의 기본 원리, 리더형·재물형·행동형·지혜형·감성형 분류, 대표 조합 예시, 조합을 읽는 순서까지 정리했습니다.",
