    useOriginalContent: true,
    contentHtml: `<p>자미두수(紫微斗數)는 흔히 '별의 학문'이라고 불린다. 그러나 자미두수에서 말하는 별(星)은 실제 천문학적 별을 관측하는 것이 아니라, 인간의 성격과 삶의 흐름을 상징적으로 표현하는 에너지의 체계다.</p>
<p>이 수많은 별 가운데 가장 중요한 것이 바로 14주성(十四主星)이다. 14주성은 명반의 중심축을 이루는 핵심 별로서, 사람의 기질과 가치관, 행동 방식, 직업 성향, 인간관계, 삶의 방향을 결정하는 가장 중요한 요소다.</p>
<p>하지만 14주성은 단순히 '좋은 별'과 '나쁜 별'로 나눌 수 있는 존재가 아니다. 각각의 별은 고유한 역할과 장단점을 가지고 있으며, 어느 궁(宮)에 위치하는지, 어떤 별과 함께하는지, 그리고 사화(四化)의 영향을 어떻게 받는지에 따라 그 의미는 크게 달라진다.</p>
<h2>14주성이란 무엇인가?</h2>
<p>14주성은 자미두수 명반에서 중심적인 역할을 하는 열네 개의 주된 별이다. 이들은 단순한 성격 표시가 아니라, 인간이 가진 다양한 능력과 심리, 삶의 방향성을 상징한다. 14주성은 자미성·천기성·태양성·무곡성·천동성·염정성·천부성·태음성·탐랑성·거문성·천상성·천량성·칠살성·파군성이다. 이 열네 개의 별이 명반의 주요 궁에 배치되면서 개인의 삶을 입체적으로 표현한다.</p>
<h2>14주성은 사람의 성격만 보는 것이 아니다</h2>
<p>초보자는 흔히 "주성은 성격을 보는 별"이라고 생각하지만, 이는 매우 제한적인 이해다. 주성은 사고방식·가치관·행동 원리·재능·문제 해결 방식·인간관계의 특징·직업 적성·리더십 유형·성공을 이루는 방식까지 함께 나타낸다. 즉, 주성은 '나는 어떤 사람인가?'뿐 아니라 '나는 어떻게 살아가는가?'까지 설명하는 핵심 열쇠다.</p>
<h2>자미두수의 두 축 — 북두성과 남두성</h2>
<p>14주성은 전통적으로 북두성과 남두성의 두 계열로 나누어 이해한다.</p>
<h3>북두성 계열</h3>
<p>자미성·무곡성·염정성·거문성·파군성·탐랑성·칠살성. 변화와 개척, 현실적 성취, 경쟁, 추진력과 관련된 성향이 강하다.</p>
<h3>남두성 계열</h3>
<p>천부성·천기성·태양성·태음성·천동성·천상성·천량성. 안정, 조화, 보호, 성장, 인간관계와 관련된 성향을 강조하는 경우가 많다.</p>
<p>이 구분은 절대적인 길흉을 의미하는 것이 아니라, 각 별이 세상을 대하는 기본적인 방식의 차이를 이해하는 데 도움이 된다.</p>
<h2>14주성의 기본 성격</h2>
<p>자미성은 제왕과 통솔력을, 천기성은 전략가와 기획자를, 태양성은 빛과 봉사·정의를, 무곡성은 재물과 실행력을, 천동성은 온화함과 적응력을, 염정성은 원칙과 변화·열정을, 천부성은 안정과 관리 능력을, 태음성은 지혜와 축적·섬세함을, 탐랑성은 욕망과 매력·창의성을, 거문성은 언변과 분석·비판적 사고를, 천상성은 균형과 조정 능력을, 천량성은 보호와 도덕성·책임감을, 칠살성은 결단력과 개척 정신을, 파군성은 혁신과 변화를 상징한다. 이러한 상징은 해석의 출발점일 뿐이며, 실제 의미는 명반 전체의 구조 속에서 결정된다.</p>
<h2>좋은 별과 나쁜 별은 존재하는가?</h2>
<p>자미두수를 처음 배우는 사람들은 "어떤 별이 가장 좋은가?"라는 질문을 자주 한다. 그러나 전통 자미두수에서는 모든 별에는 장점과 과제가 함께 존재한다고 본다.</p>
<p>자미성은 리더십과 품격을 상징하지만 자존심이 지나치면 독선으로 이어질 수 있다. 탐랑성은 뛰어난 사교성과 창의성을 지녔지만 욕망이 과하면 충동적인 선택을 할 수 있다. 칠살성과 파군성은 변화와 도전을 이끄는 강력한 힘을 갖지만, 준비 없이 움직이면 불안정성을 경험할 가능성이 있다. 반대로 천동성이나 천량성처럼 온화한 별도 지나친 신중함이나 현실 감각의 부족으로 기회를 놓칠 수 있다. 따라서 어떤 별도 절대적으로 좋거나 나쁘다고 단정할 수는 없다.</p>
<h2>14주성은 반드시 궁과 함께 해석한다</h2>
<p>같은 주성이라도 어느 궁에 위치하느냐에 따라 의미는 크게 달라진다. 예를 들어 무곡성이 명궁에 있으면 현실적이고 실행력이 뛰어난 성향으로 나타날 수 있지만, 재백궁에서는 재물 관리와 경제 활동의 방식이 더욱 강조된다. 태양성이 관록궁에 있으면 사회적 명예와 리더십이 두드러질 수 있고, 부부궁에서는 배우자의 성향이나 관계의 특징으로 해석될 수 있다. 즉, 별은 에너지이고 궁은 그 에너지가 작용하는 삶의 영역이다.</p>
<h2>별은 서로 영향을 주고받는다</h2>
<p>14주성은 혼자 존재하지 않는다. 명반에서는 여러 주성과 보조성이 함께 배치되며, 길성·흉성·사화가 더해져 복합적인 구조를 만든다. 자미성과 천부성이 함께하면 안정적인 리더십이 강화될 수 있으며, 무곡성과 탐랑성이 조화를 이루면 사업 감각과 실행력이 뛰어난 모습으로 나타나기도 한다. 반대로 일부 조합에서는 성향의 충돌이나 내적 갈등이 커질 수도 있다. 따라서 한 개의 별만 보고 결론을 내리는 것은 자미두수의 해석 원리에 맞지 않는다.</p>
<h2>14주성을 배우는 올바른 순서</h2>
<p>효율적으로 14주성을 익히기 위해서는 각 주성의 기본 상징과 성격을 이해하고, 별이 담당하는 강점과 약점을 함께 익히고, 주성이 각 궁에 들어갔을 때의 의미를 학습하고, 주성 간의 조합과 상호작용을 이해하고, 사화와 대운·세운이 주성에 미치는 영향을 함께 해석하는 순서를 권한다. 이 과정을 거치면 별을 단순히 암기하는 것이 아니라, 명반 속에서 살아 움직이는 구조로 이해할 수 있다.</p>
<h2>결론</h2>
<p>14주성은 자미두수 명반의 핵심 언어다. 각각의 별은 인간이 가진 다양한 성향과 가능성을 상징하며, 명궁을 비롯한 여러 궁에서 삶의 여러 측면을 드러낸다.</p>
<p>그러나 주성의 의미는 결코 고정되어 있지 않다. 궁의 위치, 별의 조합, 사화의 작용, 대운과 세운의 흐름에 따라 같은 별도 전혀 다른 모습으로 발현될 수 있다. 따라서 자미두수를 깊이 이해하려면 14주성을 개별적인 성격 유형으로 암기하는 데 그치지 말고, 명반 전체 속에서 서로 연결되고 변화하는 하나의 유기적인 체계로 이해해야 한다.</p>
<p>이러한 관점에서 14주성은 단순한 '별'이 아니라, 인간의 삶과 운명을 읽어내는 가장 중요한 해석의 언어라 할 수 있다.</p>`,
