    description:
      "사주 궁합 보는 법의 핵심은 점수가 아니라 두 사람의 작동 방식입니다. 일간 관계, 오행 밸런스, 십성 역할 조합으로 궁합을 읽는 순서와 실전 체크리스트를 정리했습니다.",
