<p>트라인만 많은 관계가 최고라는 건 오해입니다. 마찰 각도가 하나도 없으면 자극도 성장도 약해지기 쉽고, 스퀘어가 있어도 그 지점을 언어화해 다루면 오히려 단단해집니다.</p>
