    description: "자미두수 궁합은 부처궁 하나만으로 판단하지 않습니다. 명궁·복덕궁·재백궁·사화·길성흉성·대운유년까지 종합해 배우자 운과 관계의 흐름을 읽는 정통 해석 순서를 정리했습니다.",
