      "숙요점 27수는 달의 궤도를 27구간으로 나눈 별자리 체계로, 태어난 날 달이 머문 자리가 본명숙이 됩니다. 27수의 유래(나크샤트라·숙요경)부터 관계 읽기의 기본 틀까지 첫 입문 가이드입니다.",
