    description: "숙요점에서는 같은 명·업태·안괴 관계라도 상대와 몇 숙 떨어져 있는지에 따라 기운의 작용 방식이 달라집니다. 근거리·중거리·원거리 3분류의 본질과 각각의 장단점, 연애·결혼·사업에서의 체감을 정리했습니다.",
