    description: "관계의 질은 큰 이벤트가 아니라 매일 반복되는 작은 행동에서 결정됩니다. 숙요점 관점에서 매일·매주·매월·매년 단위로 관계 리듬을 관리하는 실천 루틴을 정리했습니다.",
    category: "숙요점",
