      "숙요점 27숙 수호 동물의 유래(나크샤트라 요니 체계)와 표준 매칭표를 정리했습니다. 상징 동물과 요니 동물의 차이, 궁합에서 동물 상성을 읽는 법까지 담은 대백과입니다.",
    category: "숙요점",
