    title: insightArticleText("ia_2107_prop_title"),
    description:
      "돼지점 같은 동물 징후 점복부터 주역·룬·차잎점·지오맨시까지, 세계 이색 점술을 문화사와 현대 활용 관점으로 정리했습니다. 4가지 비교 프레임으로 읽는 점복 문화 가이드입니다.",
    category: "비교 가이드",
