    useOriginalContent: true,
    contentHtml: `<h2>1단계. 현재 대운(10년 운) 확인 ★★★★★</h2>
<p>가장 중요합니다.</p>
<p>좋은 경우 — 용신운으로 들어왔다, 희신운이다, 기신운이 끝나간다, 대운 천간이 나를 돕는다, 대운 지지가 직업운을 살린다 → 적극적인 이직 검토.</p>
<p>나쁜 경우 — 기신 대운이다, 충이 심하다, 형살이 지속된다, 재성·관성이 모두 무너진다 → 이직보다 버티는 것이 유리.</p>
<h2>2단계. 올해(세운) 확인 ★★★★★</h2>
<p>올해가 어떤 기운인지 확인합니다.</p>
<p>좋은 신호 — 관성이 들어온다(승진·좋은 회사·직책 상승), 재성이 들어온다(연봉 상승·성과급·사업 확장), 식상이 강해진다(이직 성공·프리랜서·창업).</p>
<p>주의 — 상관견관, 충이 심함, 형살, 천극지충 → 퇴사 충동은 커지지만 결과가 좋지 않을 가능성.</p>
<h2>3단계. 월운 확인 ★★★★</h2>
<p>실제 이직은 월운이 결정하는 경우가 많습니다. 체크: 면접운·합격운·계약운·이동운·문서운.</p>
<p>좋은 월 — 합, 생, 귀인(천을귀인·월덕·천덕). 나쁜 월 — 충, 형, 파, 해, 공망.</p>
<h2>4단계. 관성 변화 체크</h2>
<p>직장운은 관성이 핵심입니다. 정관 증가 → 안정적 회사·공기업·대기업·승진. 편관 증가 → 스타트업·외국계·경쟁·책임 증가. 관성 붕괴 → 조직 스트레스·상사 문제·퇴사 가능성.</p>
<h2>5단계. 재성 체크</h2>
<p>재성이 좋아지는 시기 — 연봉 상승, 스카우트, 투자, 인센티브. 재성이 약해지는 시기 — 연봉 감소, 계약 실패, 돈이 안 모임.</p>
<h2>6단계. 식상 체크</h2>
<p>식상이 강해질 경우 — 능력 인정, 포트폴리오 강화, 이직 성공, 프리랜서 성공. 너무 강하면 — 말실수, 상사 충돌, 퇴사 충동.</p>
<h2>7단계. 비겁 체크</h2>
<p>비겁 증가의 장점 — 동료 도움, 공동창업, 네트워크. 단점 — 경쟁 심화, 연봉 협상 실패, 돈 나감.</p>
<h2>8단계. 충(沖) 체크 ★★★★★</h2>
<p>충은 이동을 의미합니다. 좋은 충 — 이사, 이직, 승진, 해외 이동. 나쁜 충 — 갑작스러운 퇴사, 회사 구조조정, 계약 파기.</p>
<h2>9단계. 합(合) 체크</h2>
<p>합이 많으면 좋은 회사 연결, 인맥 소개, 헤드헌팅, 계약 성사가 따릅니다.</p>
<h2>10단계. 귀인 체크</h2>
<p>귀인이 들어오면 좋은 상사, 추천, 스카우트, 면접 합격이 따릅니다. 대표 귀인 — 천을귀인, 천덕귀인, 월덕귀인, 복성귀인.</p>
<h2>11단계. 문서운</h2>
<p>이직은 문서운입니다. 체크: 계약서, 연봉계약, 오퍼레터, 입사서류. 문서운이 좋으면 계약이 쉽게 됩니다.</p>
<h2>12단계. 이동운</h2>
<p>역마가 들어오면 해외, 출장, 이직, 부서 이동, 사업 확장이 따릅니다.</p>
<h2>13단계. 건강운</h2>
<p>건강이 무너지면 좋은 회사도 오래 다니기 어렵습니다. 체크: 스트레스, 불면, 위장, 허리, 멘탈.</p>
<h2>14단계. 인간관계</h2>
<p>관계운이 좋으면 상사·동료·고객·팀워크 모두 좋아집니다.</p>
<h2>15단계. 현실 체크 (가장 중요)</h2>
<p>아무리 사주가 좋아도 업계 침체, 경기 악화, 준비 부족이면 실패 가능성이 높습니다. 반대로 사주가 조금 약해도 포트폴리오, 자격증, 영어, 면접 준비, 네트워크가 충분하면 성공 확률은 높아질 수 있습니다.</p>
<h2>이직 점수표</h2>
<p>각 항목을 체크합니다.</p>
<ul>
<li>대운 좋음 (+20)</li>
<li>세운 좋음 (+15)</li>
<li>월운 좋음 (+10)</li>
<li>관성 상승 (+10)</li>
<li>재성 상승 (+10)</li>
<li>식상 상승 (+10)</li>
<li>귀인 (+10)</li>
<li>합 많음 (+5)</li>
<li>이동운 (+5)</li>
<li>문서운 (+5)</li>
</ul>
<p>감점 요소</p>
<ul>
<li>충 심함 (-10)</li>
<li>형살 (-5)</li>
<li>공망 (-5)</li>
<li>상관견관 (-10)</li>
<li>건강 악화 (-10)</li>
<li>현실 준비 부족 (-20)</li>
</ul>
<h2>총점 해석</h2>
<table>
<thead><tr><th>점수 구간</th><th>해석</th></tr></thead>
<tbody>
<tr><td>90~100점</td><td>매우 좋은 이직 시기. 충분한 준비가 되어 있다면 적극적으로 기회를 잡을 만한 때로 해석한다.</td></tr>
<tr><td>75~89점</td><td>좋은 기회가 들어올 가능성이 있는 시기. 조건을 꼼꼼히 비교하며 움직이는 전략이 적합하다.</td></tr>
<tr><td>60~74점</td><td>신중한 접근이 필요한 구간. 현 직장을 유지하면서 병행 준비를 권장한다.</td></tr>
<tr><td>40~59점</td><td>변화를 서두르기보다 역량 강화와 시장 탐색에 집중하는 편이 유리하다.</td></tr>
<tr><td>39점 이하</td><td>명리학적으로는 큰 변화를 피하고 기반을 다지는 시기로 해석하는 경우가 많다.</td></tr>
</tbody>
</table>
<h2>개인 맞춤 분석을 원한다면</h2>
<p>보다 정교한 분석을 위해서는 출생연도·출생월·출생일·출생시간(가능하면 정확한 시간)·성별·양력/음력 여부가 필요합니다. 이 정보를 바탕으로 대운, 세운, 월운, 용신·희신, 직업 적성, 이직 적기와 주의 시기 등을 종합적으로 분석해 다양한 경우의 수를 검토할 수 있습니다.</p>`,
