    contentHtml: `<!-- target keyword: 다샤 | secondary: 빔쇼타리 다샤, 마하다샤, 안타르다샤 -->
<p><strong>다샤(Dasha)</strong>는 베다점성술에서 "지금 인생의 어떤 주제가 전면에 올라와 있는가"를 보여주는 행성 기간 체계입니다. 표준인 <strong>빔쇼타리 다샤</strong>는 120년을 9개 행성 기간으로 나누며, 초보자는 복잡한 계산보다 현재 마하다샤·안타르다샤의 키워드를 월간 행동 1개로 번역하는 것부터 시작하면 됩니다.</p>

<h2>빔쇼타리 다샤의 기본 구조</h2>
<p>빔쇼타리 다샤는 출생 시 달이 머문 나크샤트라(27수)의 주행성에서 첫 다샤가 시작되고, 이후 정해진 순서로 이어집니다. 각 행성의 마하다샤(대기간)는 케투 7년, 금성 20년, 태양 6년, 달 10년, 화성 7년, 라후 18년, 목성 16년, 토성 19년, 수성 17년 — 합이 120년입니다.</p>
<p>각 마하다샤 안에는 같은 순서로 <strong>안타르다샤</strong>(부기간, 북티라고도 부름)가 돌고, 그 안에 다시 프라티안타르다샤가 있습니다. 실전에서는 마하다샤가 큰 계절, 안타르다샤가 그 계절 속 날씨라고 이해하면 충분합니다.</p>

<h2>초보자용 3단계 해석법</h2>
<ul>
<li><strong>1단계</strong>: 현재 마하다샤 주행성의 핵심 성향을 파악합니다.</li>
<li><strong>2단계</strong>: 안타르다샤 행성이 더하는 보조 주제를 확인합니다.</li>
<li><strong>3단계</strong>: 두 키워드를 조합해 이번 달 행동 1개를 정합니다.</li>
</ul>
<p>예를 들어 목성 마하다샤·수성 안타르다샤라면 "확장(목성)을 문서화·학습(수성)으로 뒷받침하는 시기"로 읽고, 이번 달에는 자격 과정 등록이나 포트폴리오 정리 같은 행동을 잡는 식입니다. 같은 다샤라도 그 행성이 내 차트에서 어떤 하우스를 다스리는지에 따라 결과가 달라지므로, 차트 기초는 <a href="/insights/vedic-astrology-navamsa-basics/">나밤샤 기초 가이드</a>와 함께 보면 정확도가 올라갑니다.</p>

<h2>행성별 핵심 키워드 9장</h2>
<ul>
<li><strong>태양</strong> 자기 확립·권위 / <strong>달</strong> 정서·대중 / <strong>화성</strong> 추진·경쟁</li>
<li><strong>수성</strong> 소통·거래·학습 / <strong>목성</strong> 확장·지혜·귀인 / <strong>금성</strong> 관계·취향·재화</li>
<li><strong>토성</strong> 구조·책임·인내 / <strong>라후</strong> 야망·비정형 기회 / <strong>케투</strong> 정리·내면화</li>
</ul>
<p>용어를 한꺼번에 외우지 말고 이 9개 축만 카드처럼 정리해 두세요. 쉬운 언어로 반복할수록 실전 활용도가 올라갑니다.</p>

<h2>커리어·관계·재무에 적용하기</h2>
<p>커리어에서는 다샤를 이직 확정 신호가 아니라 <strong>역량 확장 타이밍과 포지셔닝 조정 타이밍</strong>으로 씁니다. 성장 신호 구간(목성·금성·수성 계열)에는 가시적 성과를, 정리 신호 구간(토성·케투 계열)에는 구조 개선과 학습에 비중을 둡니다. 관계에서는 표현 방식과 경계 설정을, 재무에서는 지출 구조와 리스크 한도를 먼저 점검하세요. 다샤와 고차르(트랜짓)를 함께 읽고 레머디까지 연결하는 방법은 <a href="/insights/vedic-dasha-transit-remedy-practical-guide/">다샤·트랜짓·레머디 실전 가이드</a>에 정리했습니다.</p>

<h2>월간 복기 루틴</h2>
<p>월초에 "이번 달 다샤 키워드 행동 1개"를 정하고, 월말에 실제로 그 주제의 사건·기회가 있었는지 한 줄 복기합니다. 3개월만 쌓여도 내 차트에서 다샤가 작동하는 방식이 체감으로 잡힙니다. 기록 체계가 필요하면 <a href="/insights/vedic-transit-journal-template-90days/">90일 트랜짓 저널 템플릿</a>을 활용하세요.</p>

<h2>안전한 활용 원칙</h2>
<p>다샤는 결정 대행 시스템이 아니라 판단 보조 프레임입니다. 건강·법률·투자 같은 고위험 사안은 전문가 검토를 우선하고, 다샤 해석은 행동 계획을 정교화하는 데만 쓰세요.</p>

<p>내 현재 마하다샤·안타르다샤가 궁금하다면 <a href="/vedic/">무료 베다 차트 분석</a>에서 확인하고, 대화형 해석은 <a href="/vedic-ai/">베다 AI 상담</a>으로 이어가 보세요.</p>`,
