const NON_ESSENTIAL_CATEGORIES = new Set([
  "상담 윤리",
  "콘텐츠 운영",
  "사용자 가이드",
  "기술 SEO",
  "운영 체크리스트",
  "법률/운영",
  "통합 리다이렉트",
]);

const DEFAULT_ARTICLE_AUTHOR = {
  name: "꽃돼지 연이",
  role: "명리학 연구자 · 운세 콘텐츠 에디터",
  profileUrl: "/about",
};

function normalizeArticleMeta(article) {
  const existingAuthor = article?.author;
  const author =
    existingAuthor && typeof existingAuthor === "object"
      ? {
          ...DEFAULT_ARTICLE_AUTHOR,
          ...existingAuthor,
          name: String(existingAuthor.name || DEFAULT_ARTICLE_AUTHOR.name),
          role: String(existingAuthor.role || DEFAULT_ARTICLE_AUTHOR.role),
          profileUrl: String(existingAuthor.profileUrl || DEFAULT_ARTICLE_AUTHOR.profileUrl),
        }
      : { ...DEFAULT_ARTICLE_AUTHOR };

  const references = Array.isArray(article?.references)
    ? article.references
        .map((item) => {
          if (!item || typeof item !== "object") return null;
          const title = String(item.title || "").trim();
          const url = String(item.url || "").trim();
          if (!title) return null;
          return {
            title,
            ...(url ? { url } : {}),
          };
        })
        .filter(Boolean)
    : [];

  const methodologyNote = String(
    article?.methodologyNote ||
      "본 콘텐츠는 전통 해석 체계와 편집 가이드를 바탕으로 작성되며, 결과는 자기성찰 및 참고 목적입니다.",
  );

  return {
    ...article,
    author,
    references,
    methodologyNote,
  };
}

export const INSIGHT_ARTICLES = Array.from(
  RAW_INSIGHT_ARTICLES.filter((article) => !NON_ESSENTIAL_CATEGORIES.has(article.category))
    .map(normalizeArticleMeta)
    .reduce((map, article) => {
      const slug = String(article?.slug || "").trim();
      if (!slug || map.has(slug)) return map;
      map.set(slug, article);
      return map;
    }, new Map())
    .values(),
);

export function getArticleBySlug(slug) {
  return INSIGHT_ARTICLES.find((article) => article.slug === slug) || null;
}

export const INSIGHT_TOPICS = [
  { key: "all", label: insightArticleText("ia_2931_prop_label"), emoji: "✦" },
  { key: "saju", label: insightArticleText("ia_2932_prop_label"), emoji: "四" },
  { key: "tarot", label: insightArticleText("ia_2933_prop_label"), emoji: "☾" },
  { key: "sukuyo", label: insightArticleText("ia_2934_prop_label"), emoji: "宿" },
  { key: "vedic", label: insightArticleText("ia_2935_prop_label"), emoji: "ॐ" },
  { key: "astrology", label: insightArticleText("ia_2936_prop_label"), emoji: "♈" },
  { key: "ziwei", label: insightArticleText("ia_2937_prop_label"), emoji: "紫" },
];

function inferTopic(article) {
  const slug = String(article?.slug || "");
  const category = String(article?.category || "");
  const title = String(article?.title || "");
  const bag = `${slug} ${category} ${title}`.toLowerCase();

  if (bag.includes("sukuyo") || bag.includes("숙요")) return "sukuyo";
  if (bag.includes("vedic") || bag.includes("베다")) return "vedic";
  if (bag.includes("ziwei") || bag.includes("자미두수")) return "ziwei";
  if (bag.includes("tarot") || bag.includes("타로")) return "tarot";
  if (bag.includes("astrology") || bag.includes("점성술")) return "astrology";
  return "saju";
}

export function getTopicKey(article) {
  return inferTopic(article);
}

export function getArticlesByTopic(topicKey) {
  if (!topicKey || topicKey === "all") return INSIGHT_ARTICLES;
  return INSIGHT_ARTICLES.filter((article) => inferTopic(article) === topicKey);
}
